from pathlib import Path
import json,re
t=Path('docs/evolution/unified-storage-contract.md').read_text(encoding='utf-8')
b=re.findall(r'```json\n(.*?)\n```',t,re.S)
assert len(b)==1, 'Esperado um bloco JSON de especificacao'
d=json.loads(b[0])
assert d['status']=='especificacao-nao-executada' and d['permissions']==[]
assert d['current_paths']=={'sync_bronze':'/tmp/sintetico/base_bronze.duckdb','sync_ops':'/tmp/sintetico/ops/base_ops.sqlite','mcp_ops_default':'/tmp/sintetico/base_bronze_ops.sqlite','mcp_ops_explicit':'/tmp/sintetico/ops/base_ops.sqlite','web_bronze':'cities/<IBGE>/bronze.duckdb','web_ops':'cities/<IBGE>/ops.sqlite','web_control':'app.sqlite'}
assert d['layer_status']=={'Bronze':'atual','Silver':'a-definir','Gold':'a-definir'}
assert d['decisions']=={k:'pendente' for k in ('physical_layout','backend','stable_observation_id','default_views','legacy_precedence')}
c=d['cases']
assert set(c)=={'duas-observacoes','caminhos-explicitos','contexto-ausente'}
o=c['duas-observacoes']['observations']
assert len(o)==2 and {x['identity'] for x in o}=={'sintetica-1'}
assert [x['run'] for x in o]==['a','b'] and o[0]['payload']!=o[1]['payload'] and o[0]['fetched_at']<o[1]['fetched_at']
assert all(x['payload']['idCompra']=='sintetica-1' for x in o)
assert c['duas-observacoes']['expected']=={'bronze_observations':2,'snapshot_records':1,'selected_run':'b'}
assert c['caminhos-explicitos']['expected']=={'ops':'/tmp/sintetico/ops/base_ops.sqlite','preserves_defaults':True}
assert c['contexto-ausente']['expected']=={'exception':'FileNotFoundError','creates_files':False}
assert all(re.search(re.escape(p)+r':\d+',t) for p in ('storage.py','project_access.py','web/analytics.py','crawl_state.py','web/store.py'))
print('Conteudo estruturado conferido; runtime nao validado; revisao semantica ainda necessaria')
